component.css:
.cgg {--ink: #2a3440;--panel: #f8f0de;position: relative;width: 100%;aspect-ratio: 1672 / 941;container-type: size;overflow: hidden;border-radius: 10px;background: #0d1420;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;}
.cgg *, .cgg *::before, .cgg *::after { box-sizing: border-box; }
.cgg button { font-family: inherit; border: 0; background: none; padding: 0; margin: 0; cursor: pointer; color: inherit; }
.cgg button:focus { outline: none; }
.cgg button:focus-visible { outline: 2px solid #4e86b4; outline-offset: 1px; }
.cgg-bg { position: absolute; inset: 0; background: url("https://origin.picgo.net/2026/10/11/1000086003dcd985929cc65c78.png") center / 100% 100% no-repeat; pointer-events: none; }
.cgg-grid { position: absolute; inset: 0; }
.cgg-cell {position: absolute; width: 12.55%; height: 9.8%;border-radius: 4px; overflow: hidden; padding: 0;transition: transform .15s, box-shadow .15s, filter .15s;}
.cgg-cell img { width: 100%; height: 100%; object-fit: cover; display: block; }
@media (hover: hover) {.cgg-cell:not(.is-lock):hover { transform: translateY(-.45cqh); box-shadow: 0 .9cqh 2.2cqh #141e2d66; filter: brightness(1.07); }}
.cgg-cell:not(.is-lock):active { transform: scale(.96); }
.cgg-cell.is-lock {background: #1a23337a;display: flex; align-items: center; justify-content: center;backdrop-filter: blur(1.5px); -webkit-backdrop-filter: blur(1.5px);}
.cgg-lock { display: block; width: 2.9cqh; height: 3.9cqh; position: relative; color: #b9c4cf; opacity: .48; transition: opacity .15s;}
.cgg-lock::before { content: ""; position: absolute; left: 0; right: 0; top: 34%; bottom: 0; border-radius: .35cqh; background: currentColor; }
.cgg-lock::after { content: ""; position: absolute; top: 0; left: 15%; right: 15%; height: 36%; border: .32cqh solid currentColor; border-bottom: 0; border-radius: 100% 100% 0 0 / 200% 200% 0 0; }
.cgg-lock--gold { color: #d9b46a; opacity: .58; }
@media (hover: hover) {.cgg-cell.is-lock:hover { background: #1a2333b8; } .cgg-cell.is-lock:hover .cgg-lock { opacity: .8; }}
#cgBack { position: absolute; left: 1.5%; top: 91.8%; width: 11.5%; height: 5.5%; border-radius: 6px; }
@media (hover: hover) {#cgBack:hover { background: #2d56803d; box-shadow: inset 0 0 0 2px #4e86b480; }}
.cgg-view {position: absolute; inset: 0; z-index: 9;display: flex; align-items: center; justify-content: center;background: #0d1420e8;opacity: 0; pointer-events: none; transition: opacity .25s;}
.cgg-view.is-open { opacity: 1; pointer-events: auto; }
.cgg-view img { max-width: 88%; max-height: 84%; border-radius: 6px; box-shadow: 0 2cqh 6cqh #000000ab; cursor: pointer; }
.cgg-vbar {position: absolute; left: 0; right: 0; bottom: 0;padding: 5cqh 3cqw 2.4cqh;background: linear-gradient(#00000000, #000000d9);display: flex; align-items: baseline; justify-content: center; gap: 1.4cqw;}
.cgg-vbar b { font-size: 2.3cqh; color: var(--panel); white-space: nowrap; }
.cgg-vbar span { font-size: 2.2cqh; color: #f8f0decc; }
.cgg-nav {position: absolute; top: 50%; transform: translateY(-50%);width: 4cqw; height: 7.6cqh;border-radius: 50%;background: #f8f0de21; color: var(--panel);font-size: 4.8cqh; line-height: 1;display: flex; align-items: center; justify-content: center;transition: background .15s;}
.cgg-nav--r { right: 1.2cqw; }
#cgPrev { left: 1.2cqw; }
@media (hover: hover) {.cgg-nav:hover { background: #2d5680a6; }}
#cgClose {position: absolute; top: 2.2cqh; right: 2cqw;width: 5.6cqh; height: 5.6cqh;border-radius: 50%;background: #f8f0de21; color: var(--panel);font-size: 2.5cqh;display: flex; align-items: center; justify-content: center;transition: background .15s;}
@media (hover: hover) {#cgClose:hover { background: #8a3030c4; }}

component.script:
"use strict";(() => {(() => {
// 组件标签需运行时拼接（fromCharCode 36 即美元符），规避 Workshop 的参数正则替换
let TAG = n => "<" + String.fromCharCode(36) + n + String.fromCharCode(36) + ">";
let END = n => "</" + String.fromCharCode(36) + n + String.fromCharCode(36) + ">";

let root = document.getElementById("cgRoot");
if (!root) return;
let qs = s => root.querySelector(s);

let IMG = "https://origin.picgo.net/2026/10/20/";
let NAMES = { A: "秦瑾", B: "林戌岚", C: "乌尔里克" };
let CAPS = {
A1:"在车上 · 那个时",A2:"在车后座睡觉",A3:"在旅馆洗澡时",A4:"睡着时",A5:"篝火旁",A6:"车上睡觉 · 主驾驶",A7:"加油站时",A8:"尝试 · 那个时",
B1:"在车上喝水",B2:"下车了",B3:"摘花",B4:"在地上摆pose喝水",B5:"耍帅喝水 · 放下杯子时",B6:"做烧烤",B7:"民宿太热了 · 脱上衣时",B8:"在民宿刚穿上衣服",
C1:"开车刚上路时",C2:"篝火旁的夜晚",C3:"停车休息 · 望天空",C4:"自己 · 那个时",C5:"晚上在野外看星星",C6:"早上刚起床",C7:"晚上下车休息",C8:"旅馆里查看疲惫的脚"
};
let FILES = {
A1:"10000861656376ba6773ac62ec.png",A2:"1000086163dcfbc61b06adb774.png",A3:"1000086316355c5a89b233f72d.png",A4:"1000086164e22142db4f5769ff.png",A5:"100008631581f6e00748abf5bc.png",A6:"100008631421daf42150a16ba6.png",A7:"1000086317a5febdc653a56462.png",A8:"100008616645374a90dddc3f8a.png",
B1:"1000086155d8aa3fecd389ec54.jpg",B2:"1000086156d8633bbaf3cfd25e.jpg",B3:"10000861576c64db2b8c74ebb7.jpg",B4:"100008615814948ac4a04473c3.jpg",B5:"10000861591cc874792df16809.jpg",B6:"1000086160a6cdc10868c7ae75.jpg",B7:"100008616173b1ddef0cf8aae9.jpg",B8:"10000861629cf75370e4725061.jpg",
C1:"1000086169c9bc528f1c2dc532.jpg",C2:"10000861684b450f1b0b48bee8.jpg",C3:"10000861675f82e63036932ba1.jpg",C4:"100008617100c1ef26ff80a6f4.jpg",C5:"1000086173df523ad44c60f707.jpg",C6:"1000086174bd29680c472147a3.jpg",C7:"1000086172fee03b69aa7a02a2.jpg",C8:"10000861703fe7f44288ca5b06.jpg"
};
let PRIVATE = new Set(["A1","A3","A4","A8","B7","B8","C4","C8"]); // 亲密度满级解锁
let ROWS = [{ r: "B", row: 0 }, { r: "C", row: 1 }, { r: "A", row: 2 }];
let COLS = [40.4, 53.9, 67.5, 81.3];
let TOPS = [21.1, 32.5, 45.4, 56.9, 70, 81.4];

let parse = s => {
  let set = new Set, re = /([ABCLWH])([1-8])/g, m;
  while (m = re.exec((s || "").toUpperCase())) {
    let L = ({ L: "B", W: "C", H: "A", A: "A", B: "B", C: "C" } || {})[m[1]] || m[1];
    set.add(L + m[2]);
  }
  return set;
};

// 已解锁集合：满级参数 ∪ 放映机收录记录（初始全部锁定）
let unlocked = parse(root.dataset.unlock || "");
let cells = [];
let grid = qs("#cgGrid");
let vRow = -1, vCol = -1;

let view, vImg, vName, vCap;

let openCG = code => {
  let c = cells.find(c => c.code === code);
  if (!c || !c.open) return;
  vRow = code.charCodeAt(0) - 65; vCol = parseInt(code.charAt(1), 10) - 1;
  vImg.src = IMG + FILES[code];
  vName.textContent = NAMES[code.charAt(0)] + " · CG " + code.charAt(1);
  vCap.textContent = CAPS[code];
  view.classList.add("is-open");
};
let stepCG = dir => {
  let row = cells.filter(c => c.code.charCodeAt(0) - 65 === vRow && c.open);
  if (!row.length) return;
  let idx = row.findIndex(c => c.code.charAt(1) === String.fromCharCode(48 + vCol + 1));
  openCG(row[(idx + dir + row.length) % row.length].code);
};

let render = () => {
  grid.innerHTML = ""; cells.length = 0;
  ROWS.forEach(rc => {
    for (let n = 1; n <= 8; n++) {
      let code = rc.r + n;
      let isOpen = unlocked.has(code); // 唯一判定：收录记录或满级参数
      cells.push({ code, open: isOpen });
      let cell = document.createElement("button");
      cell.className = "cgg-cell" + (isOpen ? "" : " is-lock");
      cell.style.left = COLS[(n - 1) % 4] + "%";
      cell.style.top = TOPS[rc.row * 2 + Math.floor((n - 1) / 4)] + "%";
      cell.setAttribute("aria-label", code);
      if (isOpen) {
        let img = document.createElement("img");
        img.src = IMG + FILES[code]; img.alt = ""; img.loading = "lazy";
        cell.appendChild(img);
        cell.addEventListener("click", () => openCG(code));
      } else {
        let lock = document.createElement("i");
        lock.className = "cgg-lock" + (PRIVATE.has(code) ? " cgg-lock--gold" : "");
        cell.appendChild(lock);
        cell.addEventListener("click", () => toast(PRIVATE.has(code)
          ? "「" + NAMES[rc.r] + "」的这段回忆，需要亲密度满级才能解锁。"
          : "这段回忆还没有发生。继续旅程，它会自己点亮。"));
      }
      grid.appendChild(cell);
    }
  });
};
render();

// 桥函数读取放映机收录（localStorage 兜底），点亮后重渲染
{
  let KEY = "都CG";
  let local = () => { try { return localStorage.getItem(KEY) || ""; } catch (e) { return ""; } };
  let p;
  try {
    p = typeof readFromLocal === "function"
      ? Promise.resolve(readFromLocal(KEY)).catch(local)
      : Promise.resolve(local());
  } catch (e) { p = Promise.resolve(local()); }
  p.then(v => {
    let set = parse((v || "") + local());
    let changed = false;
    set.forEach(c => { if (!unlocked.has(c)) { unlocked.add(c); changed = true; } });
    if (changed) render();
  }).catch(() => {});
}

view = qs("#cgView"); vImg = qs("#cgVImg"); vName = qs("#cgVName"); vCap = qs("#cgVCap");
qs("#cgPrev").addEventListener("click", () => stepCG(-1));
qs("#cgNext").addEventListener("click", () => stepCG(1));
vImg.addEventListener("click", () => stepCG(1));
let close = () => view.classList.remove("is-open");
qs("#cgClose").addEventListener("click", close);
view.addEventListener("click", e => { if (e.target === view) close(); });
document.addEventListener("keydown", e => {
  if (!view.classList.contains("is-open")) return;
  if (e.key === "Escape") close();
  else if (e.key === "ArrowLeft") stepCG(-1);
  else if (e.key === "ArrowRight") stepCG(1);
});
qs("#cgBack").addEventListener("click", () => {
  changeMsg("【玩家合上了CG相册，回到了标题界面。】\n\n" + TAG("大都会标题页") + "<页面>标题</页面><动画>完成</动画><状态></状态>" + END("大都会标题页"));
});
})()})();
